GO
CREATE VIEW [dbo].[vw_BookList] AS SELECT b.Id, b.BookCode, b.ISBN, b.Title, b.PublishYear, b.PageCount, c.Id AS CategoryId, c.CategoryName, a.Id AS AuthorId, a.AuthorName, p.Id AS PublisherId, p.PublisherName, b.SellingPrice, b.Quantity, b.MinStock, CASE WHEN b.Quantity = 0 THEN N'Het hang' WHEN b.Quantity <= b.MinStock THEN N'Sap het' ELSE N'Con hang' END AS StockStatus, b.Description, b.ImagePath, b.IsActive, b.CreatedAt, b.UpdatedAt FROM Books b JOIN Categories c ON b.CategoryId = c.Id LEFT JOIN Authors a ON b.AuthorId = a.Id LEFT JOIN Publishers p ON b.PublisherId = p.Id;
