/****** Object:  View [dbo].[vw_SalesOrderDetailFull]    Script Date: 7/13/2026 12:48:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =========================
-- 3.2 CHI TIET HOA DON
-- =========================
CREATE VIEW [dbo].[vw_SalesOrderDetailFull]
AS
SELECT 
    so.Id AS SalesOrderId,
    so.OrderCode,
    so.OrderDate,

    u.Id AS StaffId,
    u.FullName AS StaffName,

    c.Id AS CustomerId,
    c.FullName AS CustomerName,

    b.Id AS BookId,
    b.BookCode,
    b.Title,

    sod.Quantity,
    sod.UnitPrice,
    sod.DiscountAmount,
    sod.LineTotal,

    so.TotalAmount,
    so.PaymentMethod,
    so.OrderStatus,
    so.Note
FROM SalesOrders so
JOIN Users u ON so.UserId = u.Id
LEFT JOIN Customers c ON so.CustomerId = c.Id
JOIN SalesOrderDetails sod ON so.Id = sod.SalesOrderId
JOIN Books b ON sod.BookId = b.Id;
GO
