-- =========================
-- 3.3 SACH SAP HET HANG
-- =========================
CREATE VIEW [dbo].[vw_LowStockBooks]
AS
SELECT 
    Id,
    BookCode,
    Title,
    Quantity,
    MinStock
FROM Books
WHERE Quantity <= MinStock
AND IsActive = 1;
GO
/****** Object:  View [dbo].[vw_DailyRevenue]    Script Date: 7/13/2026 12:48:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =========================
-- 3.4 DOANH THU THEO NGAY
-- =========================
CREATE VIEW [dbo].[vw_DailyRevenue]
AS
SELECT
    CAST(OrderDate AS DATE) AS RevenueDate,
    COUNT(*) AS TotalOrders,
    SUM(TotalAmount) AS TotalRevenue
FROM SalesOrders
WHERE OrderStatus = 'Completed'
GROUP BY CAST(OrderDate AS DATE);
GO
/****** Object:  View [dbo].[vw_TopSellingBooks]    Script Date: 7/13/2026 12:48:28 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- =========================
-- 3.5 SACH BAN CHAY
-- =========================
CREATE VIEW [dbo].[vw_TopSellingBooks]
AS
SELECT
    b.Id AS BookId,
    b.BookCode,
    b.Title,
    SUM(sod.Quantity) AS TotalSold,
    SUM(sod.LineTotal) AS TotalRevenue
FROM SalesOrderDetails sod
JOIN SalesOrders so ON sod.SalesOrderId = so.Id
JOIN Books b ON sod.BookId = b.Id
WHERE so.OrderStatus = 'Completed'
GROUP BY b.Id, b.BookCode, b.Title;
GO
