-- 3.6 LICH SU KHO
-- =========================
CREATE VIEW [dbo].[vw_InventoryHistory]
AS
SELECT
    it.Id,
    b.Id AS BookId,
    b.BookCode,
    b.Title,
    u.Id AS StaffId,
    u.FullName AS StaffName,
    it.TransactionType,
    it.QuantityChange,
    it.ReferenceType,
    it.ReferenceId,
    it.Note,
    it.CreatedAt
FROM InventoryTransactions it
JOIN Books b ON it.BookId = b.Id
LEFT JOIN Users u ON it.UserId = u.Id;
