-- =========================
-- 3.7 DANH SACH HOA DON
-- =========================
CREATE VIEW [dbo].[vw_SalesOrderList]
AS
SELECT
    so.Id,
    so.OrderCode,
    so.OrderDate,
    so.StoreId,
    st.StoreName,
    u.Id AS StaffId,
    u.FullName AS StaffName,
    c.Id AS CustomerId,
    ISNULL(c.FullName, N'Khach le') AS CustomerName,
    so.TotalAmount,
    so.PaymentMethod,
    so.OrderStatus,
    so.Note
FROM SalesOrders so
JOIN Stores st ON so.StoreId = st.Id
JOIN Users u ON so.UserId = u.Id
LEFT JOIN Customers c ON so.CustomerId = c.Id;
GO
