/****** Object:  StoredProcedure [dbo].[sp_AdjustBookStock]    Script Date: 7/13/2026 12:48:29 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* ============================================================
   4. STORED PROCEDURE CHINH KHO THU CONG
   ============================================================ */

CREATE PROCEDURE [dbo].[sp_AdjustBookStock]
    @BookId INT,
    @UserId INT,
    @QuantityChange INT,
    @Note NVARCHAR(255) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM Books WHERE Id = @BookId)
    BEGIN
        RAISERROR (N'Sach khong ton tai.', 16, 1);
        RETURN;
    END;

    IF NOT EXISTS (SELECT 1 FROM Users WHERE Id = @UserId)
    BEGIN
        RAISERROR (N'Nguoi dung khong ton tai.', 16, 1);
        RETURN;
    END;

    IF EXISTS (
        SELECT 1
        FROM Books
        WHERE Id = @BookId
          AND Quantity + @QuantityChange < 0
    )
    BEGIN
        RAISERROR (N'So luong dieu chinh lam ton kho bi am.', 16, 1);
        RETURN;
    END;

    UPDATE Books
    SET Quantity = Quantity + @QuantityChange,
        UpdatedAt = SYSDATETIME()
    WHERE Id = @BookId;

    INSERT INTO InventoryTransactions (
        BookId,
        UserId,
        TransactionType,
        QuantityChange,
        ReferenceType,
        ReferenceId,
        Note
    )
    VALUES (
        @BookId,
        @UserId,
        'Adjustment',
        @QuantityChange,
        'Manual',
        NULL,
        ISNULL(@Note, N'Dieu chinh ton kho thu cong')
    );
END;
GO
